// Check for overlap first
if (box1.Max[0] >= box2.Min[0] && box1.Min[0] <= box2.Max[0] &&
    box1.Max[1] >= box2.Min[1] && box1.Min[1] <= box2.Max[1] &&
    box1.Max[2] >= box2.Min[2] && box1.Min[2] <= box2.Max[2])
{
    return BoxRelation::Overlapped;
}

// Check for adjacency - boxes touch but don't overlap
bool adjacent = false;

// Check each dimension for adjacency
for (int dim = 0; dim < 3; ++dim)
{
    // Check if boxes are adjacent along this dimension
    if ((std::abs(box1.Max[dim] - box2.Min[dim]) < 1e-10) ||
        (std::abs(box2.Max[dim] - box1.Min[dim]) < 1e-10))
    {
        // Check if they overlap in the other two dimensions
        int dim1 = (dim + 1) % 3;
        int dim2 = (dim + 2) % 3;

        if (box1.Max[dim1] >= box2.Min[dim1] && box1.Min[dim1] <= box2.Max[dim1] &&
            box1.Max[dim2] >= box2.Min[dim2] && box1.Min[dim2] <= box2.Max[dim2])
        {
            adjacent = true;
            break;
        }
    }
}

if (adjacent)
{
    return BoxRelation::Adjacent;
}

// Otherwise, boxes are separated
return BoxRelation::Separated;

